define card {
  id 312015 as CrownOfWatatsumi;
  since "v4.1.0";
  cost DiceType.Aligned, 1;
  artifact {
    variable healedPts, 0 {
      visible false;
    };
    variable bubble, 0 { range 2; };
    replaceDescription "[GCG_TOKEN_SHIELD]",
      ((_, self) => self.variables.healedPts);
    on healed {
      listenTo samePlayer;
      :variables.healedPts += :e.value;
      const totalPts = :variables.healedPts;
      const generatedBubbleCount = Math.floor(totalPts / 3);
      const restPts = totalPts % 3;
      :variables.bubble += generatedBubbleCount;
      :variables.healedPts = restPts;
    };
    on increaseSkillDamage {
      const bubbleCount = :variables.bubble;
      :variables.bubble = 0;
      :e.increaseDamage(bubbleCount);
    };
  };
};

