        damageValue: radiantHuesEchoesInEffect.variables.damageValue,
      },
    });
  }
  // [浮彩·实像] 打出浮彩时：抓等于此状态层数张牌。
  const radiantHuesManifestationInEffect = :query(
    $.my.combatStatus.def(RadiantHuesManifestationInEffect),
