define skill {
  id 14144 as CaloricBalancingPlan01;
  skillType passive {
    variable switchCount, 0;
    variable gainNightsoulPassiveUsagePerRound, 3;
    defineSnippet {
      const nightsoul = :self.hasNightsoulsBlessing();
      if (!nightsoul) {
        return;
      }
      if (nightsoul.variables.nightsoul === 2) {
        :heal(1, $.macros.myMostInjured);
      } else {
        :gainNightsoul(:self);
      }
      :variables.gainNightsoulPassiveUsagePerRound! -= 1;
    };
    // 我方角色准备技能
    on entityEnter {
      when :(
        :self.hasNightsoulsBlessing() &&
          :variables.gainNightsoulPassiveUsagePerRound &&
          :e.entity.definition.type === "status" &&
          :e.entity.definition.tags.includes("preparingSkill")
      );
      listenTo samePlayer;
      :callSnippet();
    };
    // 或累计2次……
    on switchActive {
      when :( :self.hasNightsoulsBlessing() );
      listenTo samePlayer;
      :variables.switchCount! += 1;
    };
    // ……「切换角色」后
    on switchActive {
      when :(
        :self.hasNightsoulsBlessing() &&
          :variables.gainNightsoulPassiveUsagePerRound &&
          :variables.switchCount! % 2 === 0
      );
      listenTo samePlayer;
      :callSnippet();
    };
    on roundEnd {
      :variables.gainNightsoulPassiveUsagePerRound = 3;
    };
  };
};

