          shieldValue += shield.variables.shield!;
        } else {
          shieldValue += 2;
        }
        shield.dispose();
      }
      if (shieldValue > 0) {
        :characterStatus(ArmoredCrabCarapace, :self, {
          overrideVariables: {
            shield: shieldValue,
          },
        });
